{
  "promos": [
    {
      "title": "A Stranger's Vow",
      "start_block": "B056",
      "end_block": "B118",
      "hook": "A tall, rugged man in a worn dark trench coat emerges from the shadows of the cathedral aisle, his heavy boots echoing as the entire congregation watches in stunned silence.",
      "cliffhanger": "The Bearded Stranger drops to one knee before Lady Juliana, holding up a silver ring as she gazes down at him with fresh tears and a trembling smile of hope, the swelling score holding on the unresolved proposal.",
      "why": "It opens with a mysterious hero's dramatic entrance, builds through a brutal takedown of a guard and a public shaming of the family, and ends on a marriage proposal that leaves the answer hanging.",
      "context_gap": "A stranger would not know the stranger is secretly a duke, but the visual storytelling makes his power and Juliana's desperation clear."
    },
    {
      "title": "Discarded and Dragged Away",
      "start_block": "B019",
      "end_block": "B059",
      "hook": "An imperious Noble Matriarch in a black velvet gown steps forward and coldly declares, \"Enough, Juliana. You have humiliated this family enough for one day.\"",
      "cliffhanger": "The Bearded Stranger steps into the aisle and commands in a low, thunderous voice, \"Take your hands off her,\" as the Noble Matriarch freezes in shock and outrage.",
      "why": "It starts with a brutal family rejection, escalates to guards physically dragging a screaming bride from the church, and cuts on a mysterious stranger's threatening intervention before any fight resolves.",
      "context_gap": "A stranger would not know the full history of the betrayal, but the visual of a woman in a wedding gown being dragged from a church is instantly legible."
    },
    {
      "title": "You Stole My Wedding",
      "start_block": "B002",
      "end_block": "B047",
      "hook": "A Lady in a gold gown smirks beside Gerald and mocks Juliana: \"Look at you... still clinging to that little locket as if it can make you worthy of a place here.\"",
      "cliffhanger": "The Noble Matriarch barks \"Guards! Remove her!\" and the guards seize Juliana's arms as she screams \"Let me go!\"",
      "why": "It opens on a cruel taunt that instantly establishes the villain and victim, builds through Juliana's defiant exposure of her family's betrayal, and cuts on her being violently dragged away before any rescue.",
      "context_gap": "A stranger would not know the sister stole the fiancé, but the dialogue makes the betrayal clear within seconds."
    }
  ],
  "moments": [
    {
      "start_block": "B002",
      "end_block": "B017",
      "kind": "hook",
      "description": "The Lady in Gold Gown taunts Juliana that she stole her wedding, declaring \"Now it is mine\" while Gerald stands silently beside her."
    },
    {
      "start_block": "B040",
      "end_block": "B047",
      "kind": "cliffhanger",
      "description": "The Noble Matriarch leans in with vicious delight and tells Juliana \"Not anymore,\" then orders the guards to remove her as Juliana screams."
    },
    {
      "start_block": "B059",
      "end_block": "B072",
      "kind": "hook",
      "description": "The Bearded Stranger commands the guards to release Juliana, then effortlessly drops an armed guard with a devastating strike."
    },
    {
      "start_block": "B111",
      "end_block": "B118",
      "kind": "cliffhanger",
      "description": "The Bearded Stranger drops to one knee before Lady Juliana, offering a silver ring as she gazes down at him with tears and a trembling smile of hope."
    }
  ]
}
